def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r - 1][c] == 2 and
                grid[r + 1][c] == 2 and grid[r][c - 1] == 2 and
                grid[r][c + 1] == 2):
                centers.append((r, c))

    # Connect neighboring diamonds that are aligned, filling only the gap
    # between their outward-facing tips.
    for r in range(h):
        row_centers = sorted(c for rr, c in centers if rr == r)
        for c1, c2 in zip(row_centers, row_centers[1:]):
            for c in range(c1 + 2, c2 - 1):
                if grid[r][c] == 0:
                    out[r][c] = 1

    for c in range(w):
        col_centers = sorted(r for r, cc in centers if cc == c)
        for r1, r2 in zip(col_centers, col_centers[1:]):
            for r in range(r1 + 2, r2 - 1):
                if grid[r][c] == 0:
                    out[r][c] = 1

    return out
